public ProdReportedError avaParmInventHandlingQty(ProdReportedError _avaReportedErrorQty = avaReportedErrorQty)
{
    avaReportedErrorQty = _avaReportedErrorQty;

    return avaReportedErrorQty;
}

/// <summary>
/// Sets fields on the <c>ProdParmReportFinished</c> for finished main product record for a standard Production Order.
/// </summary>
protected void setProdParmReportFinishedMainProductFieldsForProdItem()
{
    next setProdParmReportFinishedMainProductFieldsForProdItem();

    if (PdsGlobal::pdsIsCWItem(prodParmReportFinishedMainProduct.ItemId))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
    else
    {
        prodParmReportFinishedMainProduct.QtyError  = this.avaParmInventHandlingQty();
    }
}

/// <summary>
/// Initializes the <c>ProdParmReportFinished</c> for finished reported product record for Batch Order with one co/by product.
/// </summary>
/// <param name = "_inventDimLocal">
/// A <c>InventDim</c> record
/// </param>
/// <param name = "_parmId">
/// The generated <c>ParmId</c>
/// </param>
/// <param name = "_pmfProdCoBy">
/// A <c>PmfProdCoBy</c> record
/// </param>
/// <param name = "_transDate">
/// The current date.
/// </param>
protected void initProdParmReportFinishedReportedProductForCoByProduct(InventDim _inventDimLocal,
                                                                        ParmId _parmId,
                                                                        PmfProdCoBy _pmfProdCoBy,
                                                                        TransDate _transDate)
{
    next initProdParmReportFinishedReportedProductForCoByProduct(_inventDimLocal,
                                                                _parmId, 
                                                                _pmfProdCoBy, 
                                                                _transDate);

    if (PdsGlobal::pdsIsCWItem(prodParmReportFinishedReportedProduct.ItemId))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
    else
    {
        prodParmReportFinishedReportedProduct.QtyError      = this.avaParmInventHandlingQty();
        prodParmReportFinishedReportedProduct.PdsCWBatchErr = 0;
    }
}

/// <summary>
/// Determines if the work must be created.
/// </summary>
/// <param name = "_workBuildId">The work creation number.</param>
/// <returns>true if the work must be created; otherwise, false.</returns>
protected boolean mustCreateWork(WHSWorkBuildId _workBuildId)
{
    boolean avaMustCreateWork;

    avaMustCreateWork = next mustCreateWork(_workBuildId);

    if (avaMustCreateWork && inventHandlingQty <= 0)
    {
        avaMustCreateWork = false;
    }

    return avaMustCreateWork;
}
